def _literal(value):
    if (type(value) is not str or not value or not value.isascii() or
            any(ord(char) < 32 or ord(char) == 127 for char in value) or ']==]' in value):
        raise ValueError('Representable exact fixed CMake path required')
    return '[==[' + value + ']==]'


def _selected_sources(context):
    if context['source_recipe_bindings']['source'] != SOURCE:
        raise ValueError('Fixed original Curl archive identity differs')
    if set(context['source_recipe_bindings']['recipes']) not in (
            set(), {'toolchain.cmake', 'initial-cache.cmake'}):
        raise ValueError('No external executable Curl recipe is admitted')
    files = context['source_layout']['files']
    if any(member not in files for member in REQUIRED_MEMBERS):
        raise _factory.MissingInputs(['curl-selected-ordinary-source-data'])
    for member, expected in REVIEWED_INPUTS.items():
        if files[member] != expected:
            raise ValueError('Reviewed original Curl Source/data pin differs: ' + member)
    headers = sorted(member for member in files
                     if member.startswith('include/curl/') and member.endswith('.h'))
    if not headers:
        raise _factory.MissingInputs(['curl-public-headers-data'])
    # Preserve the whole original projection: compiler/header/probe inputs are
    # ordinary data, and no unreviewed supplier entry point is executed.
    selected = [{'member': name, **copy.deepcopy(files[name])} for name in sorted(files)]
    return selected, headers


def _imported(target):
    row = DEPENDENCIES[target]
    lines = ['add_library(' + target + ' STATIC IMPORTED GLOBAL)',
        'set_target_properties(' + target + ' PROPERTIES',
        '  IMPORTED_LOCATION "${PREFIX_ROOT}/' + row['member'] + '"',
        '  INTERFACE_INCLUDE_DIRECTORIES "${PREFIX_ROOT}/include"']
    if row['definitions']:
        lines.append('  INTERFACE_COMPILE_DEFINITIONS "' + ';'.join(row['definitions']) + '"')
    if row['links']:
        lines.append('  INTERFACE_LINK_LIBRARIES "' + ';'.join(row['links']) + '"')
    return '\n'.join(lines) + ')\n'


def _dependency_modules():
    modules = {}
    text = _imported('OpenSSL::Crypto') + _imported('OpenSSL::SSL')
    text += 'set(OPENSSL_FOUND TRUE)\nset(OpenSSL_FOUND TRUE)\nset(OPENSSL_USE_STATIC_LIBS TRUE)\nset(OPENSSL_MSVC_STATIC_RT TRUE)\n'
    text += 'set(OPENSSL_VERSION "3.5.0")\nset(OPENSSL_VERSION_MAJOR 3)\nset(OPENSSL_INCLUDE_DIR "${PREFIX_ROOT}/include")\n'
    modules['FindOpenSSL.cmake'] = text
    text = _imported('ZLIB::ZLIB')
    text += 'set(ZLIB_FOUND TRUE)\nset(ZLIB_VERSION "1.3.1")\nset(ZLIB_VERSION_STRING "1.3.1")\nset(ZLIB_VERSION_MAJOR 1)\n'
    modules['FindZLIB.cmake'] = text
    text = _imported('Brotli::common') + _imported('Brotli::dec')
    text += 'set(BROTLI_FOUND TRUE)\nset(BROTLI_LIBRARIES Brotli::dec Brotli::common)\n'
    text += 'set(BROTLI_INCLUDE_DIRS "${PREFIX_ROOT}/include")\nset(BROTLI_LIBRARY_DIRS "${PREFIX_ROOT}/lib")\n'
    modules['FindBrotli.cmake'] = text
    text = _imported('FoundationNative::nghttp2')
    text += 'set(NGHTTP2_FOUND TRUE)\nset(NGHTTP2_LIBRARIES FoundationNative::nghttp2)\n'
    text += 'set(NGHTTP2_INCLUDE_DIRS "${PREFIX_ROOT}/include")\nset(NGHTTP2_LIBRARY_DIRS "${PREFIX_ROOT}/lib")\nset(NGHTTP2_VERSION "1.64.0")\n'
    modules['FindNGHTTP2.cmake'] = text
    text = _imported('ICU::data') + _imported('ICU::uc') + _imported('LibPSL::LibPSL')
    text += 'set(LIBPSL_FOUND TRUE)\nset(Libpsl_FOUND TRUE)\nset(LIBPSL_LIBRARIES LibPSL::LibPSL)\n'
    text += 'set(LIBPSL_INCLUDE_DIRS "${PREFIX_ROOT}/include")\nset(LIBPSL_LIBRARY_DIRS "${PREFIX_ROOT}/lib")\n'
    modules['FindLibpsl.cmake'] = text
    return modules


def _postcondition():
    expected = ';'.join(EXPECTED_LINKS)
    interface = ';'.join('$<LINK_ONLY:' + link + '>' for link in EXPECTED_LINKS)
    return '''
if(NOT "${_curl_version_sem}" STREQUAL "8.17.0" OR
   NOT USE_OPENSSL OR NOT HAVE_LIBZ OR NOT HAVE_BROTLI OR
   NOT USE_NGHTTP2 OR NOT USE_LIBPSL OR NOT USE_THREADS_WIN32 OR
   USE_THREADS_POSIX OR USE_WINDOWS_SSPI OR HAVE_BORINGSSL OR HAVE_AWSLC OR HAVE_LIBRESSL)
  message(FATAL_ERROR "SOURCE:curl-fixed-feature-profile-differs")
endif()
if(NOT "${CURL_LIBS}" STREQUAL "''' + expected + '''")
  message(FATAL_ERROR "SOURCE:curl-ordered-dependency-graph-differs")
endif()
get_target_property(_curl_type libcurl_static TYPE)
get_target_property(_curl_runtime libcurl_static MSVC_RUNTIME_LIBRARY)
get_target_property(_curl_direct libcurl_static LINK_LIBRARIES)
get_target_property(_curl_interface libcurl_static INTERFACE_LINK_LIBRARIES)
get_target_property(_curl_definitions libcurl_static INTERFACE_COMPILE_DEFINITIONS)
if(NOT "${_curl_type}" STREQUAL "STATIC_LIBRARY" OR
   NOT "${_curl_runtime}" STREQUAL "MultiThreaded" OR
   NOT "${_curl_direct}" STREQUAL "''' + expected + '''" OR
   NOT "${_curl_interface}" STREQUAL "''' + interface + '''" OR
   NOT "${_curl_definitions}" STREQUAL "CURL_STATICLIB")
  message(FATAL_ERROR "SOURCE:curl-static-target-interface-differs")
endif()
foreach(_property IN ITEMS INTERFACE_LINK_OPTIONS LINK_OPTIONS)
  get_property(_is_set TARGET libcurl_static PROPERTY "${_property}" SET)
  if(_is_set)
    get_property(_value TARGET libcurl_static PROPERTY "${_property}")
    if(NOT "${_value}" STREQUAL "")
      message(FATAL_ERROR "SOURCE:curl-unreviewed-link-option:${_property}")
    endif()
  endif()
endforeach()
'''


def _project(context):
    text = '# Source-owned Curl static Windows graph; no supplier root execution.\n'
    text += 'cmake_minimum_required(VERSION 3.24)\ncmake_policy(SET CMP0091 NEW)\n'
    for key, value in (('SOURCE_ROOT', context['source_root']),
                       ('PREFIX_ROOT', context['prefix_root']),
                       ('PROJECT_ROOT', context['project_root'])):
        text += 'set(' + key + ' ' + _literal(value) + ')\n'
    text += 'set(CMAKE_MODULE_PATH "${PROJECT_ROOT}/modules")\n'
    text += 'set(CMAKE_FIND_PACKAGE_PREFER_CONFIG OFF)\n'
    text += 'set(CMAKE_INSTALL_PREFIX "${PREFIX_ROOT}" CACHE PATH "Fixed prefix" FORCE)\n'
    text += 'set(CMAKE_BUILD_TYPE Release CACHE STRING "Fixed configuration" FORCE)\n'
    text += 'set(CMAKE_MSVC_RUNTIME_LIBRARY MultiThreaded CACHE STRING "Static CRT" FORCE)\n'
    text += 'set(BUILD_SHARED_LIBS OFF CACHE BOOL "Static only" FORCE)\n'
    for name, enabled in sorted(OPTIONS.items()):
        text += 'set(' + name + (' ON' if enabled else ' OFF') + ' CACHE BOOL "Fixed route" FORCE)\n'
    text += 'set(CURL_CA_PATH none CACHE STRING "No ambient CA directory" FORCE)\n'
    text += 'set(CURL_CA_BUNDLE none CACHE STRING "No ambient CA file" FORCE)\n'
    for target in DEPENDENCIES:
        text += 'if(TARGET ' + target + ')\n  message(FATAL_ERROR "SOURCE:curl-preexisting-dependency-target")\nendif()\n'
    text += 'include("${PROJECT_ROOT}/configuration-1.cmake")\n'
    text += 'include("${PROJECT_ROOT}/configuration-2.cmake")\n'
    text += 'include("${PROJECT_ROOT}/library.cmake")\n'
    return text + _postcondition()


def reviewed_supplier_commands(supplier, *, identity, source_layout, build_root,
                               prefix_root, source_recipe_bindings):
    if type(supplier) is not str or supplier != 'curl':
        raise ValueError('Only the fixed Curl supplier is supported')
    context = _factory.factory_context(supplier, identity=identity,
        source_layout=source_layout, build_root=build_root, prefix_root=prefix_root,
        source_recipe_bindings=source_recipe_bindings)
    selected, headers = _selected_sources(context)
    common = _factory.render_cmake_inputs(context)
    rendered = copy.deepcopy(common['rendered_files'])
    prefix = 'recipes/curl/'
    rendered.append({'output': prefix + 'CMakeLists.txt', 'content': _project(context)})
    for name, content in TEMPLATES.items():
        rendered.append({'output': prefix + name + '.cmake', 'content': content})
    for name, content in _dependency_modules().items():
        rendered.append({'output': prefix + 'modules/' + name, 'content': content})
    rendered.sort(key=lambda row: row['output'])
    program = _factory.original_program(context, 'cmake')
    executable = program['declaration']['path']
    operations = [
        ('configure', [executable, '-S', context['project_root'], '-B', context['binary_root'],
            '-G', 'Ninja', '-C', context['cache_file'],
            '-DCMAKE_TOOLCHAIN_FILE:FILEPATH=' + context['toolchain_file']]),
        ('build', [executable, '--build', context['binary_root'], '--config', 'Release',
            '--parallel', '1', '--target', 'libcurl_static']),
        ('install', [executable, '--install', context['binary_root'], '--config', 'Release']),
    ]
    commands = [{'id': 'curl-' + stage, 'supplier': supplier, 'stage': stage,
        'program': copy.deepcopy(program), 'argv': argv, 'cwd': context['workspace_root'],
        'environment': copy.deepcopy(context['environment']),
        'initial_cache': copy.deepcopy(common['references']['initial-cache.cmake'])
            if stage == 'configure' else None,
        'response_files': [], 'log_policy': 'stdout-stderr-combined'}
        for stage, argv in operations]
    result = {'commands': commands,
        'registration': {'stages': [{key: row[key] for key in ('id', 'supplier', 'stage')}
                                   for row in commands], 'produced_tools': {}},
        'source_files': selected, 'rendered_files': rendered, 'generated_inputs': [],
        'install_artifacts': {'libraries': {'CURL::libcurl': 'lib/libcurl.lib'}, 'headers': headers}}
    return _factory.validate_factory_result(context, result)
